using System.Reflection;

namespace SourceGen.Ioc.Emit;

/// <summary>The parts that each generated file shares (Container.Output.spec, "Requirements for the generated code").</summary>
internal static class GeneratedFile
{
    /// <summary>
    /// Gets <c>[GeneratedCode]</c> with the version of the generator. The version is <c>major.minor.patch</c> without the
    /// git height, so the generated code changes only when the version changes.
    /// </summary>
    public static string GeneratedCodeAttribute { get; } =
        $"[global::System.CodeDom.Compiler.GeneratedCode(\"SourceGen.Ioc\", \"{GetVersion()}\")]";

    /// <summary>Writes the lines at the start of a generated file.</summary>
    /// <param name="writer">The writer.</param>
    public static void WriteHeader(SourceWriter writer)
    {
        writer.WriteLine("// <auto-generated/>");
        writer.WriteLine("#nullable enable annotations");
        writer.WriteLine("#nullable disable warnings");
        writer.WriteLine("#pragma warning disable SGIOCEXP001");
    }

    private static string GetVersion()
        => typeof(GeneratedFile).Assembly.GetCustomAttribute<AssemblyFileVersionAttribute>()?.Version is { } fileVersion
            && Version.TryParse(fileVersion, out Version? version)
                ? version.ToString(3)
                : "0.0.0";
}
